def solve(s, word_dict):
    words = set(word_dict)
    n = len(s)
    dp = [False] * (n + 1)
    dp[0] = True
    for i in range(n):
        if not dp[i]:
            continue
        for w in words:
            if s.startswith(w, i):
                dp[i + len(w)] = True
    return dp[n]
